def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue

        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        ph, pw = r1 - r0 + 1, c1 - c0 + 1
        pattern = [[grid[r0 + i][c0 + j] for j in range(pw)] for i in range(ph)]

        # Expand the surrounding rectangular canvas, bounded by background 8.
        top, bottom, left, right = r0, r1, c0, c1
        while top > 0 and any(grid[top-1][c] != 8 for c in range(left, right+1)):
            top -= 1
        while bottom+1 < h and any(grid[bottom+1][c] != 8 for c in range(left, right+1)):
            bottom += 1
        while left > 0 and any(grid[r][left-1] != 8 for r in range(top, bottom+1)):
            left -= 1
        while right+1 < w and any(grid[r][right+1] != 8 for r in range(top, bottom+1)):
            right += 1

        for r in range(top, bottom+1):
            for c in range(left, right+1):
                if grid[r][c] != 8:
                    out[r][c] = pattern[(r-r0) % ph][(c-c0) % pw]

    return out
